 let {sessions=[]}:GlobalWindowProps=$props();
 type Pilot={characterID:number;name:string;accountName:string};
 type MiningSite={sourceDungeonID?:number|null;siteFamily?:"ORE"|"MOON"|"ICE"|"UNKNOWN";scannerKey:number;instanceID:number;label:string;archetypeID:27|28;observedAt:number;target:{kind:"ORE_ANOMALY"|"ICE";systemID:number;name:string;siteID:number;instanceID:number;position:{x:number;y:number;z:number}}};
