 type Review={setup:JsonValue;fingerprint:string;policies:PluginRunPolicy[];pilots:Pilot[]};
 let anomaly=$state(false),ice=$state(false),moon=$state(false),commander=$state(0),burstID=$state(0),coreID=$state(0),compressorID=$state(0),tractorID=$state(0),siteID=$state(0),selfUnload=$state(false),account=$state(""),pilots=$state<Pilot[]>([]),miner1=$state(0),miner2=$state(0),hauler=$state(0),extraHaulers=$state<number[]>([]),division=$state(1),beltID=$state(0);
 let reads=$state<Record<number,Inspection>>({}),bots=$state<readonly ServerBot[]>([]),reviewed=$state<Review|null>(null),busy=$state(false),restoring=$state(true),recoveryUnavailable=$state(false),restoredActivePilots=$state<Pilot[]>([]),message=$state(""),rosterError=$state(""),recoveryError=$state("");
 const reach=createPilotReach({pass:createTrainingAccountPass(),held:()=>sessions,known:()=>[...restoredActivePilots,...pilots.filter(p=>!restoredActivePilots.some(x=>x.characterID===p.characterID))].map(p=>({characterID:p.characterID,characterName:p.name,accountName:p.accountName})),accounts:()=>[...new Set([...pilots,...restoredActivePilots].map(p=>p.accountName))]});
