 async function restoreActive(){restoring=true;try{const restored=await pointers.restore(async name=>{const options=await reach.accountOptions(name);if(!options.token)throw Error('Account authentication is unavailable.');const response=await(options.fetch??fetch)(`${options.baseUrl??''}/api/pilot-training/characters`,{headers:{authorization:`Bearer ${options.token}`},credentials:'omit'}),body=await response.json();if(!response.ok||body?.ok!==true||typeof body.account!=='string'||body.account.toLowerCase()!==name.toLowerCase()||!Array.isArray(body.characters))throw Error('Account roster is unavailable.');const pilots:Pilot[]=body.characters.map((c:any)=>{if(!Number.isSafeInteger(c?.characterID)||c.characterID<=0||typeof c.name!=='string'||!c.name)throw Error('Account roster is malformed.');return {characterID:c.characterID,name:c.name,accountName:body.account};});const current=await pluginGetJson('uoc','/runs/current',options);if(current.ok!==true||!Array.isArray(current.runs))throw Error('Current run controllers are unavailable.');const registry=current.runs as unknown as {botID:string;characterID:number;operationID:string;operationRunID:string}[],bots=await listServerBots(options);return {account:body.account,pilots,registry,bots};});restoredActivePilots=restored.pilots;recoveryError=restored.unresolved.length?'A previous fleet start or owner could not be verified; check runs before starting that pilot again.':'';}catch(e){recoveryError=e instanceof Error?e.message:String(e);}finally{recoveryUnavailable=!pointers.persistent();restoring=false;}}
 const chosen=$derived((selfUnload?[miner1,miner2]:[miner1,miner2,hauler,...extraHaulers,...(commander?[commander]:[])]).map(id=>pilots.find(p=>p.characterID===id)??null));
 const leader=$derived(reads[miner1]??null),belt=$derived(leader?.belts.find(b=>b.itemID===beltID)??null),site=$derived((ice?leader?.iceSites:moon?leader?.moonSites:leader?.oreSites)?.find(s=>s.scannerKey===siteID)??null),burst=$derived(reads[commander]?.miningBursts?.find(b=>b.moduleID===burstID)??null),core=$derived(reads[commander]?.industrialCores?.find(c=>c.moduleID===coreID)??null),compressor=$derived(reads[commander]?.compressors?.find(c=>c.moduleID===compressorID)??null),tractor=$derived(reads[commander]?.tractors?.find(c=>c.moduleID===tractorID)??null);
 const fingerprint=$derived(JSON.stringify([selfUnload,anomaly,ice,moon,siteID,miner1,miner2,hauler,extraHaulers,commander,burstID,coreID,compressorID,tractorID,division,beltID,chosen.map(p=>p?.accountName),(selfUnload?[miner1,miner2]:[miner1,miner2,hauler,...extraHaulers,...(commander?[commander]:[])]).map(id=>reads[id])]));
 const valid=$derived(!!reviewed&&reviewed.fingerprint===fingerprint);
 const fleetBots=$derived(bots.filter(b=>b.kind==="plugin"&&b.plugin?.pluginID==="uoc"&&["mcc-miner","mcc-hauler","mcc-command"].includes(b.plugin.run)));
 function clearReview(){reviewed=null;message="";}
 async function refresh(){try{const r=await reach.readServerBots();rosterError=r.allFailed?"Could not read fleet runs.":r.missing.length?`Could not read runs for ${r.missing.join(", ")}.`:"";if(!r.allFailed)bots=r.bots;}catch(e){rosterError=e instanceof Error?e.message:String(e);}}
 async function loadAccount(){const name=account.trim();if(!name||busy)return;busy=true;clearReview();try{
  const o=await reach.accountOptions(name);if(!o.token)throw Error("Account authentication is unavailable.");
  const response=await(o.fetch??fetch)(`${o.baseUrl??""}/api/pilot-training/characters`,{headers:{authorization:`Bearer ${o.token}`},credentials:"omit"}),data=await response.json();
  if(!response.ok||data?.ok!==true||typeof data.account!=="string"||data.account.toLowerCase()!==name.toLowerCase()||name!==account.trim()||!Array.isArray(data.characters))throw Error("The current account roster is unavailable.");
  const fresh:Pilot[]=data.characters.map((c:any)=>{if(!Number.isSafeInteger(c?.characterID)||c.characterID<=0||typeof c.name!=="string"||!c.name)throw Error("Account roster is malformed.");return {characterID:c.characterID,name:c.name,accountName:data.account};});
