 }catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function waitInspection(id:string,characterID:number):Promise<Inspection>{const end=Date.now()+120000;while(Date.now()<end){const r=await reach.readServerBots();if(r.allFailed||r.missing.length)throw Error("Inspection status is unavailable; check the run before retrying.");bots=r.bots;const b=r.bots.find(x=>x.botID===id);
  if(b?.endedAt){if(b.phase!=="Fleet pilot inspected")throw Error(b.why??b.pauseReason??"Pilot inspection failed.");const x=b.plugin?.readout as unknown as Inspection;
   if(!x||x.characterID!==characterID||![x.shipID,x.stationID,x.systemID,x.corporationID].every(n=>Number.isSafeInteger(n)&&n>0)||!Number.isFinite(x.canCapacityM3)||x.canCapacityM3<=0||!Number.isFinite(x.observedAt)||!Array.isArray(x.belts)||!x.fleet||(x.fleet.state!=="not-in-fleet"&&(x.fleet.state!=="ready"||!Number.isSafeInteger(x.fleet.fleetID)||x.fleet.fleetID<=0||!Array.isArray(x.fleet.memberIDs)||!x.fleet.memberIDs.includes(characterID))))throw Error("Pilot inspection readout is incomplete.");return x;}
  await new Promise(resolve=>setTimeout(resolve,1000));}throw Error("Pilot inspection timed out; check the run before retrying.");}
 async function inspect(){if(busy)return;busy=true;clearReview();reads={};beltID=0;siteID=0;try{
  const selection=chosen;if(selection.some(p=>!p)||new Set(selection.map(p=>p?.characterID)).size!==selection.length)throw Error("Select distinct pilots for each fleet role.");
  if(new Set((selection as Pilot[]).map(p=>p.accountName.toLowerCase())).size!==selection.length)throw Error("Select only one pilot from each account.");
