  for(const p of selection as Pilot[]){message=`Inspecting ${p.name}…`;const held=sessions.find(s=>s.store.get().station.online?.characterID===p.characterID);if(held)await prepareHeldPilot(held,p.characterID);
   const o=await reach.ownerOptions(p.characterID),r=await checkPluginRun("uoc","mcc-inspect",{},o);const b=await startPluginRun(p.characterID,"uoc","mcc-inspect",r.setup,createPluginRunGrant(r.policy),o);out[p.characterID]=await waitInspection(b.botID,p.characterID);
   if(JSON.stringify(initial)!==JSON.stringify(selfUnload?[miner1,miner2]:[miner1,miner2,hauler,...extraHaulers,...(commander?[commander]:[])]))throw Error("Pilot selection changed during inspection.");}
  const all=initial.map(id=>out[id]!);if(all.some(x=>x.systemID!==all[0]!.systemID||(x.characterID!==commander&&x.corporationID!==all[0]!.corporationID)))throw Error("All selected pilots must be docked in the same mining system and corporation.");
  if(commander&&selfUnload)throw Error("Command pilot is unavailable in self-unload mode.");
  if(!(selfUnload?all[0]:all[2])!.officeID)throw Error("The destination corporation has no office at this station.");
  if(new Set(all.map(x=>x.shipID)).size!==initial.length)throw Error("Distinct ships are required.");
  if(all.some(x=>x.canCapacityM3!==all[0]!.canCapacityM3))throw Error("Native container capacity observations disagree.");
  reads=out;message="Pilots inspected. Choose a target and review the operation.";
 }catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function review(){if(busy)return;busy=true;clearReview();try{
  const selection=chosen;if(selection.some(p=>!p)||new Set(selection.map(p=>p?.characterID)).size!==selection.length||!leader||(anomaly?(selfUnload||(siteID!==0&&!site)):!belt)||!reads[miner2]||(!selfUnload&&!reads[hauler])||!(selfUnload?leader:reads[hauler])?.officeID||division<1||division>7||(commander&&!burst&&!core&&!compressor&&!tractor)||(burstID!==0&&(!commander||!burst||!burst.online||!burst.chargeTypeID||!burst.chargeQuantity||!burst.chargeSupported))||(coreID!==0&&(!commander||!core||!core.online||core.availability!=="available"||core.fuel?.availability!=="available"||!core.fuel.sufficient))||(compressorID!==0&&(!commander||!compressor?.online||!core))||(tractorID!==0&&(!commander||!tractor?.online)))throw Error("Inspect the selected pilots and choose a belt and corporation division.");
  if((selfUnload?[reads[miner2]!]:[reads[miner2]!,reads[hauler]!,...extraHaulers.map(id=>reads[id]!),...(commander?[reads[commander]!]:[])]).some(x=>!x||x.systemID!==leader.systemID||(x.characterID!==commander&&x.corporationID!==leader.corporationID)||x.canCapacityM3!==leader.canCapacityM3))throw Error("Inspected pilots no longer describe one station and system.");
  const initial=fingerprint,ids=selfUnload?[miner1,miner2]:[miner1,miner2,hauler,...extraHaulers,...(commander?[commander]:[])];
