  const destination=selfUnload?leader:reads[hauler]!,setup={operationID:`mcc-${crypto.randomUUID()}`,operationRunID:crypto.randomUUID(),systemID:leader.systemID,destinationID:destination.stationID,corporationID:destination.corporationID,division,...(anomaly?(site?{site}:{siteSearch:{family:ice?"ICE" as const:moon?"MOON" as const:"ORE" as const}}):{beltID:belt!.itemID,beltName:belt!.name}),canCapacityM3:leader.canCapacityM3,...(selfUnload?{haulMode:"SELF_UNLOAD" as const}:{}),...(commander?{command:{...(burst?{moduleID:burst.moduleID,typeID:burst.typeID}:{}),...(core?{core:{moduleID:core.moduleID,typeID:core.typeID}}:{}),...(compressor?{compressor:{moduleID:compressor.moduleID,typeID:compressor.typeID}}:{}),...(tractor?{tractor:{moduleID:tractor.moduleID,typeID:tractor.typeID}}:{})}}:{}),...(moves.length?{fleetMoves:moves}:{}),members:ids.map((id,i)=>({characterID:id,shipID:reads[id]!.shipID,role:id===commander?"COMMAND":id===hauler||extraHaulers.includes(id)?"HAULER":"MINER"}))};
  const policies:PluginRunPolicy[]=[];for(let i=0;i<ids.length;i++){const o=await reach.ownerOptions(ids[i]!),r=await checkPluginRun("uoc",ids[i]===commander?"mcc-command":ids[i]===hauler||extraHaulers.includes(ids[i]!)?"mcc-hauler":"mcc-miner",setup as JsonValue,o);if(JSON.stringify(r.setup)!==JSON.stringify(setup))throw Error("The reviewed fleet setup changed.");policies.push(r.policy);}
