 }catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 async function start(){if(busy||restoring||!reviewed||!valid)return;busy=true;message="";const approved=reviewed,started:{id:string;pilot:Pilot}[]=[];reviewed=null;
  try{await restoreActive();const setup=approved.setup as {operationID:string;operationRunID:string};for(let i=0;i<approved.pilots.length;i++){const p=approved.pilots[i]!,held=sessions.find(s=>s.store.get().station.online?.characterID===p.characterID);if(held)await prepareHeldPilot(held,p.characterID);if(fingerprint!==approved.fingerprint)throw Error("Fleet selection changed.");
    const o=await reach.ownerOptions(p.characterID),runKind=p.characterID===commander?"mcc-command":p.characterID===hauler||extraHaulers.includes(p.characterID)?"mcc-hauler":"mcc-miner",grant=createPluginRunGrant(approved.policies[i]!),pointer:ActivePointer={accountName:p.accountName,characterID:p.characterID,botID:null,operationID:setup.operationID,operationRunID:setup.operationRunID,runKind};pointers.begin(pointer);recoveryUnavailable=!pointers.persistent();let b:ServerBot;try{b=await startPluginRun(p.characterID,"uoc",runKind,approved.setup,grant,o);}catch(error){if(definiteStartRefusal(error))pointers.markRefused(pointer);throw error;}started.push({id:b.botID,pilot:p});pointers.bind(pointer,b.botID);recoveryUnavailable=!pointers.persistent();}
   message="Fleet runs started. They will form and verify the native fleet before mining.";await refresh();
  }catch(e){for(const b of started){try{await pluginPostJson("uoc",`/runs/${encodeURIComponent(b.id)}/stop`,{},await reach.ownerOptions(b.pilot.characterID));}catch{/* keep the uncertain outcome visible */}}
   message=`${e instanceof Error?e.message:String(e)} Check the run roster before trying again; any started members were asked to stop.`;await refresh();}finally{busy=false;}}
 async function stop(bot:ServerBot){busy=true;try{await pluginPostJson("uoc",`/runs/${encodeURIComponent(bot.botID)}/stop`,{},await reach.ownerOptions(bot.characterID));message="Fleet stop requested; members will settle and dock.";await refresh();}catch(e){message=e instanceof Error?e.message:String(e);}finally{busy=false;}}
 onMount(()=>{const tick=skipWhileBusy(async()=>{if(busy)return;await restoreActive();if(!busy)await refresh();});void tick();const timer=setInterval(()=>void tick(),5000);return()=>{clearInterval(timer);void reach.release();};});
</script>
<section aria-label="Mining fleet">
 <h3>Mining fleet</h3><p>Two miners work one selected target and deliver raw ore to the selected corporation office.</p>
 <label>Delivery policy <select bind:value={selfUnload} onchange={()=>{if(selfUnload){extraHaulers=[];commander=0;burstID=0;coreID=0;compressorID=0;tractorID=0;anomaly=false;ice=false;moon=false;siteID=0;}clearReview();}} disabled={busy}><option value={false}>Hauler service</option><option value={true}>Miner self-unload</option></select></label>
 <label>Account <input bind:value={account} disabled={busy} placeholder="Account name" /></label><button type="button" onclick={loadAccount} disabled={busy||!account.trim()}>Load pilots</button>
 <div class="fields">
  <label>Miner 1 <select bind:value={miner1} onchange={clearReview} disabled={busy}><option value={0}>Choose pilot</option>{#each pilots as p (p.characterID)}<option value={p.characterID}>{p.name} · {p.accountName}</option>{/each}</select></label>
  <label>Miner 2 <select bind:value={miner2} onchange={clearReview} disabled={busy}><option value={0}>Choose pilot</option>{#each pilots as p (p.characterID)}<option value={p.characterID}>{p.name} · {p.accountName}</option>{/each}</select></label>
  {#if !selfUnload}<label>Hauler <select bind:value={hauler} onchange={clearReview} disabled={busy}><option value={0}>Choose pilot</option>{#each pilots as p (p.characterID)}<option value={p.characterID}>{p.name} · {p.accountName}</option>{/each}</select></label>{#each extraHaulers as _, i}<label>Hauler {i+2} <select bind:value={extraHaulers[i]} onchange={clearReview} disabled={busy}><option value={0}>Choose pilot</option>{#each pilots as p (p.characterID)}<option value={p.characterID}>{p.name} · {p.accountName}</option>{/each}</select></label><button type="button" aria-label={`Remove hauler ${i+2}`} onclick={()=>{extraHaulers=extraHaulers.filter((_,index)=>index!==i);clearReview();}} disabled={busy}>Remove</button>{/each}<button type="button" onclick={()=>{extraHaulers=[...extraHaulers,0];clearReview();}} disabled={busy}>Add hauler</button><label>Command pilot (optional) <select bind:value={commander} onchange={()=>{coreID=0;burstID=0;compressorID=0;tractorID=0;clearReview();}} disabled={busy}><option value={0}>None</option>{#each pilots as p (p.characterID)}<option value={p.characterID}>{p.name} · {p.accountName}</option>{/each}</select></label>{/if}
  <button type="button" onclick={inspect} disabled={busy||!miner1||!miner2||(!selfUnload&&!hauler)}>Inspect pilots</button>
 </div>
 {#if leader}<label>Mining target <select value={anomaly?(ice?"ice":moon?"moon":"ore"):"belt"} onchange={(e)=>{const v=e.currentTarget.value;anomaly=v!=="belt";ice=v==="ice";moon=v==="moon";siteID=0;clearReview();}} disabled={busy}><option value="belt">Asteroid belt</option><option value="ore" disabled={selfUnload}>Ordinary ore anomaly</option><option value="moon" disabled={selfUnload}>Moon ore anomaly</option><option value="ice" disabled={selfUnload}>Ice anomaly</option></select></label>
 {#if anomaly}<label>{ice?"Ice anomaly":moon?"Moon ore anomaly":"Ordinary ore anomaly"} <select bind:value={siteID} onchange={clearReview} disabled={busy||selfUnload}><option value={0}>Find automatically after Start</option>{#each (ice?leader.iceSites:moon?leader.moonSites:leader.oreSites)??[] as s (s.scannerKey)}<option value={s.scannerKey}>{s.label}</option>{/each}</select></label>{#if (ice?leader.iceSites:moon?leader.moonSites:leader.oreSites)===null}<p>Docked scanner is unavailable; automatic search runs after Start.</p>{:else if !(ice?leader.iceSites:moon?leader.moonSites:leader.oreSites)?.length}<p>No sites observed from dock; automatic search runs after Start.</p>{/if}{:else}<label>Asteroid belt <select bind:value={beltID} onchange={clearReview} disabled={busy}><option value={0}>Choose belt</option>{#each leader.belts as b (b.itemID)}<option value={b.itemID}>{b.name}</option>{/each}</select></label>{/if}
  {#if commander}<label>Mining burst <select bind:value={burstID} onchange={clearReview} disabled={busy}><option value={0}>None</option>{#each reads[commander]?.miningBursts??[] as b (b.moduleID)}<option value={b.moduleID} disabled={!b.online||!b.chargeTypeID||!b.chargeQuantity||!b.chargeSupported}>{b.name??"Mining burst"} · {b.online?"online":"offline"} · {b.chargeQuantity??"unknown"} charges{b.chargeSupported?"":" · unsupported charge"}</option>{/each}</select></label>{#if reads[commander]?.miningBursts===null}<p>Command fitting is unavailable.</p>{/if}<label>Industrial Core (optional) <select bind:value={coreID} onchange={clearReview} disabled={busy}><option value={0}>None</option>{#each reads[commander]?.industrialCores??[] as c (c.moduleID)}<option value={c.moduleID} disabled={!c.online||c.availability!=="available"||c.fuel?.availability!=="available"||!c.fuel.sufficient}>Core type {c.typeID} · {c.online?"online":"offline"} · fuel {c.fuel?.availability==="available"?`${c.fuel.availableQuantity} available / ${c.fuel.requiredQuantity} estimated per cycle`:"unknown"}</option>{/each}</select></label>{#if reads[commander]?.industrialCores===null}<p>Industrial Core fitting is unavailable.</p>{/if}<label>Compression module (optional) <select bind:value={compressorID} onchange={clearReview} disabled={busy}><option value={0}>None</option>{#each reads[commander]?.compressors??[] as c (c.moduleID)}<option value={c.moduleID} disabled={!c.online}>Compressor type {c.typeID} · {c.online?"online":"offline"}</option>{/each}</select></label><label>Tractor beam (optional) <select bind:value={tractorID} onchange={clearReview} disabled={busy}><option value={0}>None</option>{#each reads[commander]?.tractors??[] as t (t.moduleID)}<option value={t.moduleID} disabled={!t.online}>Tractor type {t.typeID} · {t.online?"online":"offline"}</option>{/each}</select></label>{#if compressorID&&!coreID}<p>Select an Industrial Core for the compressor.</p>{/if}{#if tractorID}<p>The tractor is selected for standby; it does not move containers automatically yet.</p>{/if}{/if}
  <details><summary>Advanced site details</summary><p>Unclassified mining sites: {leader.unknownSites===null?"unavailable":leader.unknownSites?.length??"unavailable"}.</p></details>
  <label>Corporation division <select bind:value={division} onchange={clearReview} disabled={busy}>{#each [1,2,3,4,5,6,7] as d}<option value={d}>{d}</option>{/each}</select></label>
  <p>Delivery: {(selfUnload?leader:reads[hauler])?.stationName??"Station name unavailable"} · {(selfUnload?leader:reads[hauler])?.corporationName??"Corporation name unavailable"} · Division {division}.</p>
  <button type="button" onclick={review} disabled={busy||(anomaly?(selfUnload||(siteID!==0&&!site)):!belt)}>Review fleet</button>
 {/if}
 {#if reviewed&&valid}<div aria-label="Fleet review"><p>Target: {anomaly?(site?.label??`Will undock and find an eligible ${ice?"ice":moon?"moon ore":"ordinary ore"} anomaly in this system`):belt?.name}. Delivery: {(selfUnload?leader:reads[hauler])?.stationName??"Station name unavailable"} · {(selfUnload?leader:reads[hauler])?.corporationName??"Corporation name unavailable"} · Division {division}.</p><p>Miners: {reviewed.pilots[0]?.name} ({reads[miner1]?.shipTypeName??"Ship name unavailable"}), {reviewed.pilots[1]?.name} ({reads[miner2]?.shipTypeName??"Ship name unavailable"}){#if !selfUnload}; hauler: {reviewed.pilots[2]?.name} ({reads[hauler]?.shipTypeName??"Ship name unavailable"}){#each extraHaulers as id}; hauler: {pilots.find(p=>p.characterID===id)?.name} ({reads[id]?.shipTypeName??"Ship name unavailable"}){/each}{#if commander}; command: {pilots.find(p=>p.characterID===commander)?.name} ({reads[commander]?.shipTypeName??"Ship name unavailable"}), {burst?`${burst.name??"mining burst"} (${burst.chargeQuantity} charges)`:"no burst"}{#if core}; Industrial Core type {core.typeID}, estimated fuel {core.fuel?.availableQuantity} available / {core.fuel?.requiredQuantity} per cycle{/if}{#if compressor}; compressor type {compressor.typeID}{/if}{#if tractor}; tractor type {tractor.typeID} (standby){/if}{/if}{/if}.</p><details><summary>Advanced details</summary><p>Station {(selfUnload?leader:reads[hauler])?.stationID}; corporation {(selfUnload?leader:reads[hauler])?.corporationID}; ships {reads[miner1]?.shipID}, {reads[miner2]?.shipID}{#if !selfUnload}, {reads[hauler]?.shipID}{/if}. Container capacity {leader?.canCapacityM3.toLocaleString()} m³.</p><p>Risks: {reviewed.policies[0]?.riskClasses.join(", ")}. Restart requires reconciliation.</p><pre>{JSON.stringify(reviewed.setup,null,2)}</pre></details><button type="button" onclick={start} disabled={busy||restoring}>Approve and start fleet</button></div>{/if}
 {#if recoveryUnavailable}<p role="status">Run controls are available in this tab; automatic recovery after reload is unavailable.</p>{/if}{#if recoveryError}<p role="alert">{recoveryError}</p>{/if}{#if message}<p role="status">{message}</p>{/if}<h4>Fleet runs</h4><button type="button" onclick={refresh} disabled={busy}>Refresh runs</button>{#if rosterError}<p role="alert">{rosterError}</p>{/if}
 {#each fleetBots as bot (bot.botID)}<div><p>{bot.characterName??"Pilot"} · {bot.phase??bot.status}{bot.endedAt?" · ended":""}</p>{#if bot.why}<p>{bot.why}</p>{/if}{#if !bot.endedAt}<button type="button" onclick={()=>stop(bot)} disabled={busy}>Stop fleet</button>{/if}</div>{/each}
</section>
<style>.fields{display:flex;flex-wrap:wrap;align-items:end;gap:.75rem}label{display:grid;gap:.25rem;margin-block:.5rem}</style>
